using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
namespace RollerSort {
 public sealed partial class RollerGame {
  sealed class Portal {public int row,col;public readonly Queue<int> next=new();public RectTransform view;public Text counter;public bool emitting;}
  readonly List<Portal> portals=new();readonly List<Vector2Int> stones=new();bool[,] reachableFloor;
  Transform sourceLayer;bool launchedFromJourney;
  Vector2 CellPoint(int row,int col)=>new((col-(LevelLayouts.Rows(level)[0].Length-1)*.5f)*LevelLayouts.Step(level),621-row*LevelLayouts.RowStep(level));
  void RebuildReachability(){var map=LevelLayouts.Rows(level);var floor=new bool[map.Length,map[0].Length];var blocked=new bool[map.Length,map[0].Length];for(int r=0;r<map.Length;r++)for(int c=0;c<map[0].Length;c++)floor[r,c]=LevelLayouts.Occupied(level,r,c);foreach(var b in boxes)if(!b.removed)blocked[b.row,b.col]=true;foreach(var p in portals)blocked[p.row,p.col]=true;foreach(var s in stones)blocked[s.y,s.x]=true;reachableFloor=BoardAccess.Reachable(floor,blocked);}
  bool Accessible(Box b)=>!b.removed&&!b.emerging&&reachableFloor!=null&&BoardAccess.TouchesExit(reachableFloor,b.row,b.col);
  void RefreshSourceAccess(bool animate=true){RebuildReachability();foreach(var b in boxes){if(b.removed||!b.view||!Accessible(b))continue;b.view.GetComponent<Image>().color=Color.white;var lid=b.view.Find("Lid") as RectTransform;if(!lid)continue;lid.name="Opening lid";if(animate)StartCoroutine(LiftLid(lid));else{lid.gameObject.SetActive(false);Destroy(lid.gameObject);}}}
  Box CreateSource(int color,int row,int col,bool emerging=false){var b=new Box{color=color,row=row,col=col,emerging=emerging};boxes.Add(b);Vector2 point=CellPoint(row,col);float width=LevelLayouts.Step(level)<53?44:53;bool hard=IsHardJourneyLevel(level)||IsVeryHardJourneyLevel(level);Picture(sourceLayer,"slot",point+Vector2.down*2,new Vector2(width-7,width-7)).SetAsFirstSibling();b.view=Picture(sourceLayer,"source-"+ColorName(color)+"-v2",point,new Vector2(width,width+4));if(hard){var depth=b.view.gameObject.AddComponent<Shadow>();depth.effectColor=new Color(0.04f,.06f,.09f,.34f);depth.effectDistance=new Vector2(0,-1.7f);}IsolateCanvas(b.view,true);b.view.GetComponent<Image>().raycastTarget=true;b.view.gameObject.AddComponent<Button>().onClick.AddListener(()=>Release(b));b.view.GetComponent<Image>().color=new Color(1,1,1,0);string lidAsset=HiddenSource(row,col)?"mystery-cover":"cover-"+ColorName(color)+"-v2";var lid=Picture(b.view,lidAsset,new Vector2(0,(width+4)/2),new Vector2(width-2,width-2));lid.name="Lid";return b;}
  // Hidden colours sit in blocks on the outer columns of the upper rows, so the
  // centre lanes and the two rows nearest the exit stay readable for planning.
  bool HiddenSource(int row,int col){if(level<6||row<2||row%3==0)return false;int cols=LevelLayouts.Rows(level)[0].Length,outer=Mathf.Max(1,cols/3);return col<outer||col>=cols-outer;}
  void CreatePortal(int row,int col,System.Random rng){var p=new Portal{row=row,col=col};var random=new[]{rng.Next(7),rng.Next(7),rng.Next(7)};foreach(int color in LevelLayouts.TunnelColors(level,col,random))p.next.Enqueue(color);Vector2 size=LevelLayouts.Step(level)<53?new Vector2(44,46):new Vector2(53,55);bool hard=IsHardJourneyLevel(level)||IsVeryHardJourneyLevel(level);p.view=Picture(sourceLayer,"tunnel-reference",CellPoint(row,col),size);var depth=p.view.gameObject.AddComponent<Shadow>();depth.effectColor=new Color(0.02f,.05f,.08f,.60f);depth.effectDistance=new Vector2(0,-3);p.counter=Label(p.view,p.next.Count.ToString(),new Vector2(0,18),22,bounds:new Vector2(45,30));portals.Add(p);}
  void TryEmitPortals(){foreach(var p in portals){if(p.emitting||p.next.Count==0||p.row<=0||boxes.Exists(b=>!b.removed&&b.row==p.row-1&&b.col==p.col))continue;p.emitting=true;StartCoroutine(EmitPortal(p));}}
  IEnumerator EmitPortal(Portal p){yield return new WaitForSeconds(.18f);var b=CreateSource(p.next.Dequeue(),p.row-1,p.col,true);p.counter.text=p.next.Count.ToString();StartCoroutine(Pop(p.view,.18f,.045f));b.view.SetSiblingIndex(p.view.GetSiblingIndex());Vector2 target=b.view.anchoredPosition,origin=target+Vector2.up*LevelLayouts.RowStep(level);Sfx("open",.35f,.85f);for(float t=0;t<.30f;){t+=GameStep;float progress=Mathf.SmoothStep(0,1,t/.30f);b.view.anchoredPosition=Vector2.Lerp(origin,target,progress);b.view.localScale=Vector3.one*Mathf.Lerp(.75f,1,progress);yield return null;}b.view.anchoredPosition=target;b.view.localScale=Vector3.one;b.emerging=false;p.emitting=false;RefreshSourceAccess();}
  void ShuffleAccessible(int index){var front=boxes.FindAll(b=>!b.removed&&Accessible(b));if(front.Count<2){Toast("Karıştırmak için iki açık kutu gerekli.");return;}inventory[index]--;SaveBoosters();UpdateInventory();StartCoroutine(ShuffleFront(front));}
 }
}
